-- Issue #184: per-space hosted legal pages (privacy / terms / refund).
--
-- Each space can host its own legal policy text at {space}.jomform.com/privacy,
-- /terms and /refund. A page is either:
--   mode = 'auto'   -> generated by the LLM (deepseek-v4-flash) from a prompt
--                      template filled with the merchant's business details,
--   mode = 'manual' -> written by the merchant directly.
-- The content (text/HTML) is stored here and rendered on the public page.
-- A page with empty content is treated as "not set" (public route 404s).
--
-- This is a NEW table (not an ALTER on a *Select table), so the migration
-- scan-drift guard is unaffected.

CREATE TABLE space_legal_pages (
    space_id UUID NOT NULL REFERENCES spaces(id) ON DELETE CASCADE,
    page_type TEXT NOT NULL CHECK (page_type IN ('privacy','terms','refund')),
    mode     TEXT NOT NULL DEFAULT 'manual' CHECK (mode IN ('auto','manual')),
    content  TEXT NOT NULL DEFAULT '',
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (space_id, page_type)
);

CREATE INDEX space_legal_pages_space_idx ON space_legal_pages (space_id);
